css:
.govsteward-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e8edf4;
    background: linear-gradient(160deg, #0b1622 0%, #112436 55%, #0e1d2c 100%);
    border-radius: 18px;
}

.govsteward-container * {
    box-sizing: border-box;
}

.govsteward-header {
    text-align: center;
    padding: 30px 22px 26px;
    background: linear-gradient(135deg, #0d2233 0%, #143a52 60%, #1c4f63 100%);
    color: #f3f8fc;
    border-radius: 16px;
    margin-bottom: 18px;
    border: 1px solid rgba(120, 170, 200, 0.18);
    box-shadow: 0 16px 40px rgba(4, 12, 20, 0.55);
    position: relative;
    overflow: hidden;
}

.govsteward-header::before {
    content: "";
    position: absolute;
    top: 14px;
    right: 18px;
    width: 34px;
    height: 34px;
    background:
        linear-gradient(#e63946, #e63946) center/12px 34px no-repeat,
        linear-gradient(#e63946, #e63946) center/34px 12px no-repeat;
    border-radius: 5px;
    opacity: 0.9;
}

.govsteward-header h1 {
    margin: 10px 0 12px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.govsteward-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffd6da;
    background: rgba(230, 57, 70, 0.16);
    border: 1px solid rgba(230, 57, 70, 0.42);
    padding: 5px 14px;
    border-radius: 999px;
}

.govsteward-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.6;
    color: #c4d6e4;
}

.govsteward-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #9fb6c8;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.govsteward-period-counter #currentDay,
.govsteward-period-counter #maxPeriods {
    font-weight: 800;
    color: #4fc3a1;
}

.govsteward-round-name {
    background: rgba(79, 195, 161, 0.16);
    color: #6fe0bf;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.govsteward-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ffb3ba;
    background: rgba(230, 57, 70, 0.14);
    border: 1px solid rgba(230, 57, 70, 0.32);
    padding: 4px 12px;
    border-radius: 999px;
}

.govsteward-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.govsteward-status-card {
    background: #122638;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid rgba(120, 170, 200, 0.14);
    box-shadow: 0 8px 22px rgba(4, 12, 20, 0.4);
    border-top: 4px solid #1c4f63;
}

.govsteward-card-trust { border-top-color: #4fc3a1; }
.govsteward-card-backlog { border-top-color: #4a90d9; }
.govsteward-card-compliance { border-top-color: #c79be8; }
.govsteward-card-budget { border-top-color: #e0a73a; }

.govsteward-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #88a0b3;
}

.govsteward-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #ffffff;
    font-variant-numeric: tabular-nums;
}

.govsteward-card-trust .govsteward-value { color: #4fc3a1; }
.govsteward-card-backlog .govsteward-value { color: #6db0ec; }
.govsteward-card-compliance .govsteward-value { color: #c79be8; }
.govsteward-card-budget .govsteward-value { color: #e8b94f; }

.govsteward-sublabel {
    font-size: 0.76rem;
    color: #7e94a6;
    line-height: 1.35;
}

.govsteward-card-trust.govsteward-trust-danger { border-top-color: #e63946; }
.govsteward-card-trust.govsteward-trust-danger .govsteward-value { color: #ff6b76; }
.govsteward-card-trust.govsteward-trust-good { border-top-color: #4fc3a1; }

.govsteward-card-compliance.govsteward-comp-danger { border-top-color: #e63946; }
.govsteward-card-compliance.govsteward-comp-danger .govsteward-value { color: #ff6b76; }

.govsteward-exposure-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #122638;
    border: 1px solid rgba(120, 170, 200, 0.16);
    color: #9fb6c8;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.govsteward-exposure-bar #exposureDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #ff6b76;
    font-weight: 800;
}

.govsteward-exposure-bar.govsteward-exposure-low #exposureDisplay { color: #4fc3a1; }
.govsteward-exposure-bar.govsteward-exposure-mid #exposureDisplay { color: #e8b94f; }

.govsteward-briefing {
    display: flex;
    gap: 14px;
    background: #122638;
    border-left: 5px solid #4fc3a1;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 8px 22px rgba(4, 12, 20, 0.35);
}

.govsteward-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.govsteward-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #ffffff;
    margin-bottom: 6px;
}

.govsteward-briefing-text {
    font-size: 0.95rem;
    line-height: 1.6;
    color: #c4d6e4;
}

.govsteward-briefing-text strong { color: #6fe0bf; }
.govsteward-briefing-text em { color: #ffb3ba; font-style: italic; }

.govsteward-usecases {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 12px;
    margin-bottom: 18px;
}

.govsteward-uc {
    background: #0f2030;
    border-radius: 12px;
    padding: 12px 14px;
    border: 1px solid rgba(120, 170, 200, 0.12);
    display: flex;
    flex-direction: column;
    gap: 4px;
    border-left: 4px solid #4a90d9;
}

.govsteward-uc-low { border-left-color: #4fc3a1; }
.govsteward-uc-high { border-left-color: #e63946; }
.govsteward-uc-med { border-left-color: #e0a73a; }

.govsteward-uc-tag {
    font-size: 0.66rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 800;
    color: #88a0b3;
}

.govsteward-uc-high .govsteward-uc-tag { color: #ff8a91; }
.govsteward-uc-low .govsteward-uc-tag { color: #6fe0bf; }

.govsteward-uc-name {
    font-size: 0.92rem;
    font-weight: 800;
    color: #eef3f8;
    line-height: 1.25;
}

.govsteward-uc-meta {
    font-size: 0.74rem;
    color: #7e94a6;
    line-height: 1.35;
}

.govsteward-controls {
    background: #122638;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid rgba(120, 170, 200, 0.14);
    box-shadow: 0 8px 22px rgba(4, 12, 20, 0.35);
}

.govsteward-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #ffffff;
    border-bottom: 2px solid rgba(120, 170, 200, 0.18);
    padding-bottom: 8px;
}

.govsteward-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #cbdae7;
    margin: 14px 0 6px;
}

.govsteward-container select,
.govsteward-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #2c4865;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0d1c2a;
    color: #eef3f8;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.govsteward-container select:focus,
.govsteward-container input[type="number"]:focus {
    outline: none;
    border-color: #4fc3a1;
    box-shadow: 0 0 0 3px rgba(79, 195, 161, 0.18);
}

.govsteward-container select option {
    background-color: #0d1c2a;
    color: #eef3f8;
}

.govsteward-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #4fc3a1;
}

.govsteward-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #9fb6c8;
    margin-top: 4px;
}

.govsteward-range-readout span:nth-child(2) {
    color: #4fc3a1;
    font-weight: 800;
}

.govsteward-hint {
    font-size: 0.8rem;
    color: #7e94a6;
    margin-top: 6px;
    line-height: 1.45;
    font-style: italic;
}

.govsteward-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.govsteward-container .btn-primary {
    background: linear-gradient(135deg, #1c4f63 0%, #4fc3a1 100%);
    border: none;
    color: #062018;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 10px 22px rgba(28, 79, 99, 0.45);
}

.govsteward-container .btn-primary:hover {
    filter: brightness(1.08);
}

.govsteward-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #2c4865;
    color: #9fb6c8;
    background: transparent;
}

.govsteward-coach {
    background: linear-gradient(160deg, #1a0e14 0%, #2a1118 100%);
    color: #f0dcdf;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    border: 1px solid rgba(230, 57, 70, 0.28);
    box-shadow: 0 8px 22px rgba(4, 12, 20, 0.4);
}

.govsteward-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ff8a91;
    margin-bottom: 8px;
}

.govsteward-coach-body {
    font-size: 0.95rem;
    line-height: 1.6;
}

.govsteward-coach-body strong { color: #ffb3ba; }
.govsteward-coach-body em { color: #6fe0bf; font-style: italic; }

.govsteward-history,
.govsteward-chart {
    background: #122638;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid rgba(120, 170, 200, 0.14);
    box-shadow: 0 8px 22px rgba(4, 12, 20, 0.35);
}

.govsteward-history h3,
.govsteward-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #ffffff;
}

.govsteward-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #c4d6e4;
}

.govsteward-container table#usfHistoryTable th {
    background: #0f2030;
    color: #6fe0bf;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #2c4865;
}

.govsteward-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid rgba(120, 170, 200, 0.12);
    color: #c4d6e4;
}

.govsteward-container table#usfHistoryTable tr:nth-child(even) td {
    background: rgba(15, 32, 48, 0.6);
}

.govsteward-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .govsteward-container {
        padding: 14px;
    }
    .govsteward-header h1 {
        font-size: 1.7rem;
    }
    .govsteward-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .govsteward-usecases {
        grid-template-columns: repeat(2, 1fr);
    }
    .govsteward-value {
        font-size: 2rem;
    }
    .govsteward-clock {
        margin-left: 0;
    }
    .govsteward-period-counter {
        font-size: 0.88rem;
    }
    .govsteward-exposure-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .govsteward-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / cabinet-debrief screen (govsteward) ---- */
.govsteward-cm { padding: 8px 4px 4px; color: #d7e0ea; }
.govsteward-cm-head { text-align: center; margin-bottom: 18px; }
.govsteward-cm-score { font-size: 3.4rem; font-weight: 800; line-height: 1; color: #4aa3df; }
.govsteward-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #7e9aa8; }
.govsteward-cm-verdict { font-size: 1.2rem; font-weight: 700; margin-top: 8px; color: #eaf1f7; }
.govsteward-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.76rem; font-weight: 700; vertical-align: middle; }
.govsteward-cm-yes { background: rgba(74,163,223,0.16); color: #4aa3df; border: 1px solid rgba(74,163,223,0.5); }
.govsteward-cm-no { background: rgba(214,120,60,0.13); color: #e0925f; border: 1px solid rgba(214,120,60,0.45); }
.govsteward-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 14px 0; }
.govsteward-cm-metric { flex: 1 1 110px; min-width: 96px; background: rgba(74,163,223,0.07); border: 1px solid rgba(74,163,223,0.22); border-radius: 10px; padding: 12px 8px; text-align: center; }
.govsteward-cm-mv { display: block; font-size: 1.5rem; font-weight: 800; color: #4aa3df; }
.govsteward-cm-ml { display: block; font-size: 0.68rem; margin-top: 4px; color: #9fb0c2; text-transform: uppercase; letter-spacing: 0.04em; }
.govsteward-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; justify-content: center; margin: 4px 0 16px; }
.govsteward-cm-chip { font-size: 0.78rem; font-weight: 600; padding: 4px 12px; border-radius: 999px; border: 1px solid transparent; }
.govsteward-cm-chip-on { background: rgba(74,163,223,0.14); color: #8fcbef; border-color: rgba(74,163,223,0.4); }
.govsteward-cm-chip-off { background: rgba(159,176,194,0.08); color: #8798a8; border-color: rgba(159,176,194,0.22); }
.govsteward-cm-debrief-title { font-weight: 700; margin: 10px 0 6px; color: #eaf1f7; }
.govsteward-cm-insights { margin: 0; padding-left: 20px; }
.govsteward-cm-insights li { margin-bottom: 9px; line-height: 1.55; font-size: 0.92rem; color: #c3cfdb; }

