(function() {
    'use strict';

    class GovStewardAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `GovTech Steward`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (KABD · Canton of Brunnental · CHF).
            this.START_TRUST = 72;          // public trust (%) — the asset to protect
            this.START_COMPLIANCE = 40;     // governance-compliance baseline (0–100)
            this.BUDGET_CAP = 6.5;          // CHF M ring-fenced this cycle
            this.BACKLOG_TOTAL = 14000;     // pending cases
            this.START_DAYS = 19;           // average processing time (days)
            this.START_EXPOSURE = 70;       // governance-exposure index (0–100, lower safer)
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    trust: this.START_TRUST,             // %
                    backlogCleared: 0,                   // cases cleared of 14,000
                    compliance: this.START_COMPLIANCE,   // governance-compliance (0–100)
                    budgetRemaining: this.BUDGET_CAP,    // CHF M
                    monitoringReserve: 0,                // CHF M ring-fenced for governance
                    exposure: this.START_EXPOSURE,       // governance-exposure index (0–100)
                    days: this.START_DAYS,               // projected processing time (days)
                    // Sticky, run-defining penalty flags — set when the error is committed,
                    // gate the top verdict and cap KPIs. A later good round cannot wash them out.
                    recklessFirst: false,    // deployed UC-2 benefits scoring first
                    noSafeguard: false,      // automated rights-affecting decision without safeguards
                    noLegal: false,          // no FADP / DPIA sign-off
                    underfunded: false,      // committed whole budget, nothing for governance
                    ignoredSkew: false,      // proceeded unchanged on biased training data
                    vulnerableFirst: false,  // sequenced highest risk onto most vulnerable
                    noGates: false,          // no monitoring gates / rollback
                    efficiencyOnly: false,   // defended purely on speed & cost
                    trustHistory: [this.START_TRUST],
                    backlogHistory: [0],
                    complianceHistory: [this.START_COMPLIANCE],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the five Common Errors — a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    origin: `staff`,
                    risk: `efficiency`,
                    equation: `speed`,
                    attention: 30,
                    priority: `uc2`,
                    safeguard: `none`,
                    legal: `skip`,
                    monitoring: 0,
                    audit: `proceed`,
                    pilot: `vulnerable`,
                    gates: `none`,
                    remediation: 0,
                    frame: `efficiency`,
                    journalist: `dismiss`,
                    probe: `defend`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const or = document.getElementById(`originInput`);
                const ri = document.getElementById(`riskInput`);
                const eq = document.getElementById(`equationInput`);
                const at = document.getElementById(`attentionInput`);
                if (or) decisions.origin = or.value;
                if (ri) decisions.risk = ri.value;
                if (eq) decisions.equation = eq.value;
                if (at) decisions.attention = parseInt(at.value, 10);
                if (!Number.isFinite(decisions.attention) || decisions.attention < 0 || decisions.attention > 100) {
                    warn(`warn_attention_range`); return false;
                }
            } else if (round === 2) {
                const pr = document.getElementById(`priorityInput`);
                const sa = document.getElementById(`safeguardInput`);
                const le = document.getElementById(`legalInput`);
                const mo = document.getElementById(`monitoringInput`);
                if (pr) decisions.priority = pr.value;
                if (sa) decisions.safeguard = sa.value;
                if (le) decisions.legal = le.value;
                if (mo) decisions.monitoring = parseInt(mo.value, 10);
                if (!Number.isFinite(decisions.monitoring) || decisions.monitoring < 0 || decisions.monitoring > 50) {
                    warn(`warn_monitoring_range`); return false;
                }
            } else if (round === 3) {
                const au = document.getElementById(`auditInput`);
                const pi = document.getElementById(`pilotInput`);
                const ga = document.getElementById(`gatesInput`);
                const re = document.getElementById(`remediationInput`);
                if (au) decisions.audit = au.value;
                if (pi) decisions.pilot = pi.value;
                if (ga) decisions.gates = ga.value;
                if (re) decisions.remediation = parseFloat(re.value);
                if (!Number.isFinite(decisions.remediation) || decisions.remediation < 0) {
                    warn(`warn_remediation_value`); return false;
                }
            } else if (round === 4) {
                const fr = document.getElementById(`frameInput`);
                const jo = document.getElementById(`journalistInput`);
                const pb = document.getElementById(`probeInput`);
                const cv = document.getElementById(`convictionInput`);
                if (fr) decisions.frame = fr.value;
                if (jo) decisions.journalist = jo.value;
                if (pb) decisions.probe = pb.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let trustDelta = 0, backlogDelta = 0, complianceDelta = 0, exposureDelta = 0, daysDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the service and the trust equation (Common Error 5 framing starts here).
                switch (d.origin) {
                    case `paper`: complianceDelta += 4; exposureDelta -= 4; coachKey = `coach_r1_paper`; break;
                    case `staff`: exposureDelta += 4; coachKey = `coach_r1_staff`; break;
                    case `citizens`: trustDelta -= 1; exposureDelta += 5; coachKey = `coach_r1_citizens`; break;
                }

                switch (d.risk) {
                    case `tiered`: complianceDelta += 8; exposureDelta -= 8; coachKey = `coach_r1_tiered`; break;
                    case `efficiency`: exposureDelta += 8; coachKey = `coach_r1_efficiency`; break;
                    case `equal`: complianceDelta += 1; exposureDelta += 2; coachKey = `coach_r1_equal`; break;
                }

                switch (d.equation) {
                    case `fairness`: trustDelta += 2; complianceDelta += 5; exposureDelta -= 6; if (d.risk === `tiered`) coachKey = `coach_r1_sharp`; break;
                    case `speed`: trustDelta -= 1; exposureDelta += 6; coachKey = `coach_r1_speed`; break;
                    case `cost`: exposureDelta += 4; coachKey = `coach_r1_cost`; break;
                }

                // Management attention on the neighbour's failure = early situational awareness.
                if (d.attention >= 60) { complianceDelta += 4; exposureDelta -= 4; }
                else if (d.attention <= 20) { exposureDelta += 4; }

                summaryKey = (d.origin === `paper` && d.risk === `tiered` && d.equation === `fairness`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Prioritize one use case + set the safeguard (Common Errors 1, 2 & the budget trap).
                switch (d.priority) {
                    case `uc1`:
                        // Low rights-impact, real efficiency — the responsible first move.
                        backlogDelta += 3200; daysDelta -= 4; trustDelta += 2; exposureDelta -= 8; complianceDelta += 3;
                        coachKey = `coach_r2_uc1`;
                        break;
                    case `uc3`:
                        // Satisfaction win, no rights-affecting automated decision.
                        backlogDelta += 1500; daysDelta -= 2; trustDelta += 3; exposureDelta -= 4;
                        coachKey = `coach_r2_uc3`;
                        break;
                    case `uc4`:
                        // Medium impact, surveillance-perception risk.
                        backlogDelta += 2200; daysDelta -= 3; trustDelta -= 2; exposureDelta += 6;
                        coachKey = `coach_r2_uc4`;
                        break;
                    case `uc2`:
                        // The neighbour's failure mode, led first — the headline anti-pattern.
                        ds.recklessFirst = true;
                        backlogDelta += 5200; daysDelta -= 7; trustDelta -= 10; exposureDelta += 20;
                        coachKey = `coach_r2_uc2`;
                        break;
                }

                // The governance safeguard — the FADP deadline is THIS round.
                const rightsAffecting = (d.priority === `uc2`);
                switch (d.safeguard) {
                    case `full`:
                        complianceDelta += 34; trustDelta += 5; exposureDelta -= 16; spend += 1.6;
                        break;
                    case `transparency`:
                        complianceDelta += 10; exposureDelta -= 2; spend += 0.6;
                        if (rightsAffecting) { ds.noSafeguard = true; trustDelta -= 4; exposureDelta += 8; coachKey = `coach_r2_partial`; }
                        break;
                    case `none`:
                        complianceDelta -= 14; trustDelta -= 6; exposureDelta += 14; spend += 0.3;
                        ds.noSafeguard = true;
                        coachKey = `coach_r2_nosafeguard`;
                        break;
                }

                // Legal sign-off under the revised FADP.
                switch (d.legal) {
                    case `dpia`: complianceDelta += 12; exposureDelta -= 8; spend += 0.4; break;
                    case `memo`: complianceDelta += 2; exposureDelta += 2; break;
                    case `skip`: ds.noLegal = true; complianceDelta -= 8; exposureDelta += 8; if (coachKey === `coach_default`) coachKey = `coach_r2_nolegal`; break;
                }

                // Build spend for the chosen use case (heavier for the ambitious UC-2).
                spend += (d.priority === `uc2`) ? 4.0 : (d.priority === `uc1` ? 2.6 : (d.priority === `uc3` ? 2.2 : 3.0));

                // Ring-fence for ongoing governance (monitoring / appeals / rollback).
                ds.monitoringReserve = Math.round((this.BUDGET_CAP * (d.monitoring / 100)) * 100) / 100;
                if (d.monitoring === 0) {
                    ds.underfunded = true;
                    exposureDelta += 8; complianceDelta -= 6;
                    if (coachKey === `coach_default` || coachKey === `coach_r2_uc1`) coachKey = `coach_r2_nomonitor`;
                } else if (d.monitoring >= 15) {
                    complianceDelta += 6; exposureDelta -= 4; trustDelta += 1;
                }

                summaryKey = (d.priority === `uc1` && d.safeguard === `full` && d.legal === `dpia` && d.monitoring >= 15) ? `sum_r2_good` :
                             (d.priority === `uc2` ? `sum_r2_reckless` :
                             (d.safeguard === `none` ? `sum_r2_nosafeguard` : `sum_r2_weak`));
            } else if (round === 3) {
                // Sequence the rollout — the data-quality audit lands (Common Errors 3 & 4).
                switch (d.audit) {
                    case `remediate`:
                        complianceDelta += 16; trustDelta += 6; exposureDelta -= 14; daysDelta += 2; // remediation costs a little speed
                        coachKey = `coach_r3_remediate`;
                        break;
                    case `narrow`:
                        complianceDelta += 8; trustDelta += 2; exposureDelta -= 6;
                        coachKey = `coach_r3_narrow`;
                        break;
                    case `proceed`:
                        ds.ignoredSkew = true;
                        complianceDelta -= 12; trustDelta -= 14; exposureDelta += 20;
                        coachKey = `coach_r3_proceed`;
                        break;
                }

                // Pilot scope — sequencing is an equity decision.
                switch (d.pilot) {
                    case `narrow`:
                        trustDelta += 5; exposureDelta -= 10; complianceDelta += 6; backlogDelta += 2400; daysDelta -= 3;
                        break;
                    case `vulnerable`:
                        ds.vulnerableFirst = true;
                        trustDelta -= 8; exposureDelta += 14; backlogDelta += 3600; daysDelta -= 4;
                        coachKey = `coach_r3_vulnerable`;
                        break;
                    case `broad`:
                        ds.vulnerableFirst = true;
                        trustDelta -= 6; exposureDelta += 16; backlogDelta += 4200; daysDelta -= 5; complianceDelta -= 6;
                        coachKey = `coach_r3_broad`;
                        break;
                }

                // Monitoring gates & rollback between phases.
                switch (d.gates) {
                    case `gated`: complianceDelta += 14; trustDelta += 4; exposureDelta -= 12; break;
                    case `report`: complianceDelta += 3; exposureDelta += 2; break;
                    case `none`: ds.noGates = true; complianceDelta -= 8; exposureDelta += 10; if (coachKey === `coach_default`) coachKey = `coach_r3_nogates`; break;
                }

                // Data-remediation / bias-monitoring spend.
                spend += d.remediation;
                if (d.remediation >= 1.5) { complianceDelta += 6; trustDelta += 2; exposureDelta -= 4; }
                else if (d.remediation <= 0 && d.audit !== `remediate`) { exposureDelta += 4; }

                if (d.audit === `remediate` && d.pilot === `narrow` && d.gates === `gated`) coachKey = `coach_r3_steward`;

                summaryKey = (d.audit === `remediate` && d.pilot === `narrow` && d.gates === `gated`) ? `sum_r3_good` :
                             (d.audit === `proceed` ? `sum_r3_skew` :
                             (d.pilot !== `narrow` ? `sum_r3_equity` : `sum_r3_weak`));
            } else if (round === 4) {
                // Defend to the oversight committee (Common Error 5).
                switch (d.frame) {
                    case `publicvalue`:
                        trustDelta += 8; complianceDelta += 6; exposureDelta -= 10;
                        coachKey = `coach_r4_publicvalue`;
                        break;
                    case `efficiency`:
                        ds.efficiencyOnly = true;
                        trustDelta -= 6; exposureDelta += 8;
                        coachKey = `coach_r4_efficiency`;
                        break;
                    case `deflect`:
                        ds.efficiencyOnly = true;
                        trustDelta -= 8; exposureDelta += 10; complianceDelta -= 4;
                        coachKey = `coach_r4_deflect`;
                        break;
                }

                switch (d.journalist) {
                    case `evidence`: trustDelta += 6; complianceDelta += 4; exposureDelta -= 8; break;
                    case `legal`: trustDelta += 1; coachKey = (coachKey === `coach_r4_publicvalue`) ? coachKey : `coach_r4_legalonly`; break;
                    case `dismiss`: trustDelta -= 6; exposureDelta += 8; coachKey = `coach_r4_dismiss`; break;
                }

                switch (d.probe) {
                    case `own`: trustDelta += 5; complianceDelta += 4; exposureDelta -= 6; if (d.frame === `publicvalue`) coachKey = `coach_r4_own`; break;
                    case `defend`: trustDelta -= 3; exposureDelta += 4; coachKey = (coachKey === `coach_default`) ? `coach_r4_defend` : coachKey; break;
                    case `blame`: trustDelta -= 6; exposureDelta += 7; complianceDelta -= 3; coachKey = `coach_r4_blame`; break;
                }

                if (d.conviction >= 60) { trustDelta += 3; exposureDelta -= 3; }
                else if (d.conviction <= 25) { trustDelta -= 2; exposureDelta += 3; }

                summaryKey = (d.frame === `publicvalue` && d.journalist === `evidence` && d.probe === `own`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply spend against the budget cap. ----
            spend = Math.round(spend * 100) / 100;
            ds.budgetRemaining = Math.round((ds.budgetRemaining - spend) * 100) / 100;
            if (ds.budgetRemaining < 0) {
                // Overspending the ring-fenced cap is itself a governance failure.
                exposureDelta += 12; complianceDelta -= 8; trustDelta -= 3;
                ds.underfunded = true;
            }

            // ---- Apply core deltas (clamped). ----
            ds.trust = Math.max(0, Math.min(100, Math.round((ds.trust + trustDelta) * 10) / 10));
            ds.compliance = Math.max(0, Math.min(100, Math.round(ds.compliance + complianceDelta)));
            ds.exposure = Math.max(0, Math.min(100, Math.round(ds.exposure + exposureDelta)));
            ds.backlogCleared = Math.max(0, Math.min(this.BACKLOG_TOTAL, ds.backlogCleared + backlogDelta));
            ds.days = Math.max(4, Math.min(this.START_DAYS, Math.round((ds.days + daysDelta) * 10) / 10));

            // ---- Sticky CAPS: the headline anti-patterns cannot reach a clean score. ----
            // Reckless first move (UC-2 led) caps trust — the highest-risk decision on 72% trust.
            if (ds.recklessFirst) ds.trust = Math.min(ds.trust, 60);
            // Unlawful automated decision (no safeguard) caps governance compliance.
            if (ds.noSafeguard) ds.compliance = Math.min(ds.compliance, 45);
            if (ds.noLegal) ds.compliance = Math.min(ds.compliance, 55);
            // Scaling the neighbour's bias caps trust hard.
            if (ds.ignoredSkew) ds.trust = Math.min(ds.trust, 48);
            // Loading risk onto the most vulnerable caps trust.
            if (ds.vulnerableFirst) ds.trust = Math.min(ds.trust, 58);

            ds.trustHistory.push(ds.trust);
            ds.backlogHistory.push(ds.backlogCleared);
            ds.complianceHistory.push(ds.compliance);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Persist composite (0-100) where express_extractMetrics reads it every period.
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                trust: ds.trust,
                trustDelta: Math.round(trustDelta * 10) / 10,
                backlogCleared: ds.backlogCleared,
                compliance: ds.compliance,
                complianceDelta: Math.round(complianceDelta),
                budgetRemaining: ds.budgetRemaining,
                exposure: ds.exposure,
                days: ds.days,
                spend: spend,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                overallScore: ds.performance.overallScore,
                score: ds.performance.overallScore
            };
        }

        _exposureLabel(v) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (v >= 60) return t(`exposure_high`);
            if (v >= 35) return t(`exposure_mid`);
            return t(`exposure_low`);
        }

        _fmtBacklog(v) {
            // Thousands separator that matches the language (en 14,000 · es 14.000).
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sep = lang === `es` ? `.` : `,`;
            return String(Math.round(Number(v))).replace(/\B(?=(\d{3})+(?!\d))/g, sep);
        }

        _fmtBudget(v) {
            // CHF, one decimal, with a localized decimal mark.
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = (Math.round(Number(v) * 10) / 10).toFixed(1);
            return `CHF ${lang === `es` ? s.replace(`.`, `,`) : s}M`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`trustDisplay`, `domainState.trust`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.govsteward-card-trust`);
                if (card) {
                    card.classList.toggle(`govsteward-trust-danger`, n < 60);
                    card.classList.toggle(`govsteward-trust-good`, n >= 70);
                }
                return `${Math.round(n)}%`;
            });

            uiManager.bind(`backlogDisplay`, `domainState.backlogCleared`, (v) => `${self._fmtBacklog(v)} / ${self._fmtBacklog(self.BACKLOG_TOTAL)}`);

            uiManager.bind(`complianceDisplay`, `domainState.compliance`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.govsteward-card-compliance`);
                if (card) card.classList.toggle(`govsteward-comp-danger`, n < 50);
                return `${Math.round(n)}`;
            });

            uiManager.bind(`budgetDisplay`, `domainState.budgetRemaining`, (v) => self._fmtBudget(Number(v)));

            uiManager.bind(`exposureDisplay`, `domainState.exposure`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.govsteward-exposure-bar`);
                if (bar) {
                    bar.classList.toggle(`govsteward-exposure-low`, n < 35);
                    bar.classList.toggle(`govsteward-exposure-mid`, n >= 35 && n < 60);
                }
                return self._exposureLabel(n);
            });

            // Attention slider readout.
            const at = document.getElementById(`attentionInput`);
            const atReadout = document.getElementById(`attentionReadout`);
            if (at && atReadout) {
                atReadout.textContent = at.value;
                at.addEventListener(`input`, function() { atReadout.textContent = at.value; });
            }

            // Monitoring slider readout.
            const mo = document.getElementById(`monitoringInput`);
            const moReadout = document.getElementById(`monitoringReadout`);
            if (mo && moReadout) {
                moReadout.textContent = mo.value;
                mo.addEventListener(`input`, function() { moReadout.textContent = mo.value; });
            }
        }

        getChartConfig() {
            return {
                govStewardChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: this._cl(`legend_trust`, `Citizen trust (%)`),
                                data: [],
                                borderColor: `#4fc3a1`,
                                backgroundColor: `rgba(79,195,161,0.14)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#4fc3a1`,
                                yAxisID: `y`
                            },
                            {
                                label: this._cl(`legend_compliance`, `Governance compliance (0–100)`),
                                data: [],
                                borderColor: `#c79be8`,
                                backgroundColor: `rgba(199,155,232,0.10)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#c79be8`,
                                yAxisID: `y`
                            },
                            {
                                label: this._cl(`legend_backlog`, `Backlog cleared (% of 14,000)`),
                                data: [],
                                borderColor: `#6db0ec`,
                                backgroundColor: `rgba(109,176,236,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#6db0ec`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#9fb6c8`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#88a0b3` }, grid: { color: `rgba(159,182,200,0.10)` },
                                title: { display: true, text: this._cl(`axis_scale`, `0–100`), color: `#88a0b3` }
                            },
                            x: {
                                ticks: { color: `#88a0b3` }, grid: { color: `rgba(159,182,200,0.06)` },
                                title: { display: true, text: this._cl(`axis_round`, `Round`), color: `#88a0b3` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.trustHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            const backlogPct = ds.backlogHistory.map((v) => Math.round((v / this.BACKLOG_TOTAL) * 100));
            return {
                govStewardChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.trustHistory.map((v) => Math.round(v)) },
                        { data: ds.complianceHistory.map((v) => Math.round(v)) },
                        { data: backlogPct }
                    ]
                }
            };
        }

        _composite(ds) {
            const trust = Math.round(ds.trust);
            const compliance = Math.round(ds.compliance);
            const backlogCleared = Math.round(ds.backlogCleared);
            const backlogPct = Math.round((backlogCleared / this.BACKLOG_TOTAL) * 100);
            return Math.round(trust * 0.40 + compliance * 0.34 + backlogPct * 0.26);
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        _gradeLabel(perf) {
            const map = {
                "Trust Spent": `grade_spent`,
                "Responsible Steward": `grade_steward`,
                "Sound Governance": `grade_sound`,
                "Efficiency Trap": `grade_efficiency`,
                "Unsafe Deployment": `grade_unsafe`,
                "Mixed Outcome": `grade_mixed`
            };
            const key = map[perf];
            return key ? this._cl(key, perf) : perf;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const trust = Math.round(ds.trust);
            const backlogCleared = Math.round(ds.backlogCleared);
            const backlogPct = Math.round((backlogCleared / this.BACKLOG_TOTAL) * 100);
            const compliance = Math.round(ds.compliance);
            const days = Math.round(ds.days * 10) / 10;
            const budgetRemaining = Math.round(ds.budgetRemaining * 100) / 100;

            // Any sticky governance failure blocks the top verdict and the clean pattern.
            const cleanGovernance = !(ds.recklessFirst || ds.noSafeguard || ds.noLegal ||
                ds.underfunded || ds.ignoredSkew || ds.vulnerableFirst || ds.noGates || ds.efficiencyOnly);

            // Composite balances public value: trust, governance, backlog relief — trust weighted most.
            const composite = Math.round(
                trust * 0.40 + compliance * 0.34 + backlogPct * 0.26
            );

            const trustHeld = trust >= 70;
            const lawful = compliance >= 75;
            const relieved = backlogPct >= 30;

            let pattern = `mixed`;
            if (ds.recklessFirst || (ds.ignoredSkew)) pattern = `efficiency`;
            else if (ds.vulnerableFirst || ds.noSafeguard) pattern = `unsafe`;
            else if (cleanGovernance && trustHeld && lawful && relieved) pattern = `steward`;
            else pattern = `mixed`;

            let performance = `Trust Spent`;
            if (cleanGovernance && trustHeld && lawful && relieved && composite >= 75) performance = `Responsible Steward`;
            else if (cleanGovernance && lawful && trust >= 65) performance = `Sound Governance`;
            else if (ds.recklessFirst || ds.ignoredSkew) performance = `Efficiency Trap`;
            else if (ds.noSafeguard || ds.vulnerableFirst) performance = `Unsafe Deployment`;
            else if (composite >= 55) performance = `Mixed Outcome`;

            const insights = [];
            if (performance === `Responsible Steward`) insights.push(window.mySimulation.t(`insight_steward`));
            else if (pattern === `efficiency`) insights.push(window.mySimulation.t(`insight_efficiency`));
            else if (pattern === `unsafe`) insights.push(window.mySimulation.t(`insight_unsafe`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (ds.recklessFirst) insights.push(window.mySimulation.t(`insight_reckless`));
            if (ds.noSafeguard) insights.push(window.mySimulation.t(`insight_nosafeguard`));
            if (ds.ignoredSkew) insights.push(window.mySimulation.t(`insight_skew`));
            if (ds.vulnerableFirst) insights.push(window.mySimulation.t(`insight_vulnerable`));
            if (ds.underfunded) insights.push(window.mySimulation.t(`insight_underfunded`));
            if (ds.efficiencyOnly) insights.push(window.mySimulation.t(`insight_efficiencyonly`));
            if (cleanGovernance && trustHeld && !relieved) insights.push(window.mySimulation.t(`insight_cautious`));

            return {
                trust: trust,
                backlogCleared: backlogCleared,
                backlogPct: backlogPct,
                compliance: compliance,
                days: days,
                budgetRemaining: budgetRemaining,
                trustHeld: trustHeld,
                lawful: lawful,
                relieved: relieved,
                cleanGovernance: cleanGovernance,
                pattern: pattern,
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                met: (cleanGovernance && trustHeld && lawful && relieved && composite >= 75),
                performance: performance,
                performanceLabel: this._gradeLabel(performance),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const self = this;
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function (k) { return window.mySimulation.t(k); }
                : function (k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.totalScore === `number` ? s.totalScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const verdict = s.performanceLabel || s.performance || ``;
            const met = !!s.met;
            const badge = met
                ? `<span class="govsteward-cm-badge govsteward-cm-yes">` + T(`cm_met`) + `</span>`
                : `<span class="govsteward-cm-badge govsteward-cm-no">` + T(`cm_notmet`) + `</span>`;
            const chip = function (ok, key) {
                return `<span class="govsteward-cm-chip ` + (ok ? `govsteward-cm-chip-on` : `govsteward-cm-chip-off`) + `">`
                    + (ok ? `✓ ` : `· `) + T(key) + `</span>`;
            };
            const chips = chip(!!s.trustHeld, `cm_b_trust`) + chip(!!s.lawful, `cm_b_lawful`)
                + chip(!!s.relieved, `cm_b_relieved`) + chip(!!s.cleanGovernance, `cm_b_clean`);
            const md = function (val, key) {
                return `<div class="govsteward-cm-metric"><span class="govsteward-cm-mv">` + val
                    + `</span><span class="govsteward-cm-ml">` + T(key) + `</span></div>`;
            };
            const metrics = md(Math.round(s.trust || 0) + `%`, `cm_m_trust`)
                + md(Math.round(s.compliance || 0), `cm_m_compliance`)
                + md(Math.round(s.backlogPct || 0) + `%`, `cm_m_backlog`)
                + md(self._fmtBudget(s.budgetRemaining || 0), `cm_m_budget`);
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function (t) { return `<li>` + t + `</li>`; }).join(``);
            return `<div class="govsteward-cm">`
                + `<div class="govsteward-cm-head">`
                +   `<div class="govsteward-cm-score">` + score + `<span class="govsteward-cm-score-max">/100</span></div>`
                +   `<div class="govsteward-cm-verdict">` + verdict + ` ` + badge + `</div>`
                + `</div>`
                + `<div class="govsteward-cm-metrics">` + metrics + `</div>`
                + `<div class="govsteward-cm-chips">` + chips + `</div>`
                + `<div class="govsteward-cm-debrief-title">` + T(`cm_debrief`) + `</div>`
                + `<ul class="govsteward-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.ignoredSkew) return window.mySimulation.t(`hint_skew`);
            if (ds.recklessFirst) return window.mySimulation.t(`hint_reckless`);
            if (ds.noSafeguard) return window.mySimulation.t(`hint_nosafeguard`);
            if (ds.exposure >= 65) return window.mySimulation.t(`hint_exposure`);
            if (ds.underfunded && state.currentPeriod >= 2) return window.mySimulation.t(`hint_underfunded`);
            if (ds.compliance < 50 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_compliance`);
            if (ds.trust >= 70 && ds.compliance >= 75) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.trust`, label: `Trust`, i18nKey: `col_trust`, formatter: (v) => `${Math.round(v)}%` },
                { key: `results.compliance`, label: `Compliance`, i18nKey: `col_compliance`, formatter: (v) => `${Math.round(v)}` },
                { key: `results.backlogCleared`, label: `Backlog`, i18nKey: `col_backlog`, formatter: (v) => self._fmtBacklog(v) },
                { key: `results.budgetRemaining`, label: `Budget`, i18nKey: `col_budget`, formatter: (v) => self._fmtBudget(Number(v)) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

        getTranslations() {
